   944  otError NcpBase::HandleCommandPropertySet(uint8_t aHeader, spinel_prop_key_t aKey)
   945  {
   946      otError         error   = OT_ERROR_NONE;
   947      PropertyHandler handler = FindSetPropertyHandler(aKey);
   948
   949      if (handler != NULL)
   950      {
   951          mDisableStreamWrite = false;
   952          error               = (this->*handler)();
   953          mDisableStreamWrite = true;
   954      }
   955      else
   956      {
   957          // If there is no "set" handler, check if this property is one of the
   958          // ones that require different treatment.
   959
   960          bool didHandle = HandlePropertySetForSpecialProperties(aHeader, aKey, error);
   961
   962          VerifyOrExit(!didHandle);
   963
   964  #if OPENTHREAD_ENABLE_NCP_VENDOR_HOOK
   965          if (aKey >= SPINEL_PROP_VENDOR__BEGIN && aKey < SPINEL_PROP_VENDOR__END)
   966          {
   967              mDisableStreamWrite = false;
   968              error               = VendorSetPropertyHandler(aKey);
   969              mDisableStreamWrite = true;
   970
   971              // An `OT_ERROR_NOT_FOUND` status from vendor handler indicates
   972              // that it does not support the given property key. In that
   973              // case, `didHandle` is set to `false` so a `LAST_STATUS` with
   974              // `PROP_NOT_FOUND` is emitted. Otherwise, we fall through to
   975              // prepare the response.
   976
   977              didHandle = (error != OT_ERROR_NOT_FOUND);
   978          }
   979  #endif
   980
   981          VerifyOrExit(didHandle, error = PrepareLastStatusResponse(aHeader, SPINEL_STATUS_PROP_NOT_FOUND));
   982      }
   983
   984      if (error == OT_ERROR_NONE)
   985      {
   986          error = PrepareSetResponse(aHeader, aKey);
   987      }
   988      else
   989      {
   990          error = PrepareLastStatusResponse(aHeader, ThreadErrorToSpinelStatus(error));
   991      }
   992
   993  exit:
   994      return error;
   995  }
